// Maps — everything the apex knows about it: origin, gateway allowlist, route, Apps-section
// entry (web-app-suite.md F4). Generated by scripts/new-web-app.sh; adding this file IS the
// registration (`registry/index.ts` globs `apps/*.ts`).
import type { ProxyMethodAllowlist } from '@tenshu/sdk/bridge'
import { appOrigin, SESSION_METHODS, type HostedApp } from '../types'

declare global {
  interface ImportMetaEnv {
    /** The Maps app's origin (see `apps/registry/apps/maps.ts`). */
    readonly VITE_MAPS_ORIGIN?: string
  }
}

// ⚠⚠ F5 — exactly the methods `web/maps` calls: its `ProxyMethod` table in
// `web/maps/src/lib/proxy.ts` (`gatewayPermissions.test.ts` fails on drift either way). Exact
// names only; a `.*` prefix only for a namespace this app owns outright, and never a bare `'*'`.
// ⚠ Not granted, on purpose (`maps-app.md` §Web scope → Decided): no saved / note / list method
// (5a — none exists); of Timeline only `timeline.placeVisitSummary`, for the visit stats (5b), and
// `timeline.places` (place rows, no moments) to break the list map's anchor tie — not
// `timeline.place` (it ships every visit moment), no feed, no moments, no role / merge writes;
// of `mapRegion.*` only the two `<TenshuMap>` calls — no `regionsIn` / `catalog`, because the web
// manages no offline regions (3). Nothing of another
// app's: no `fs.*`, no `contact.*`, no `calendar.*`.
const METHODS: ProxyMethodAllowlist = [
  ...SESSION_METHODS,
  'place.list',
  'place.list.observe',
  'place.get',
  'place.rename',
  'timeline.placeVisitSummary',
  'timeline.places',
  'mapRegion.regionAt',
  'mapRegion.streamRange',
]

const PROD_ORIGIN = 'https://maps.tenshu.app'

export const maps: HostedApp = {
  id: 'maps',
  order: 40,
  title: 'Maps',
  prodOrigin: PROD_ORIGIN,
  envName: 'VITE_MAPS_ORIGIN',
  devPort: 5179,
  origin: () => appOrigin(import.meta.env.VITE_MAPS_ORIGIN, PROD_ORIGIN, 5179),
  methods: METHODS,
  routePath: 'maps/*',
  sections: [''],
  // ⚠ DISPLAY data for the Apps section — what the app can actually call is `methods` above.
  manifest: {
    id: 'maps',
    label: 'Maps',
    description: 'Your places, end-to-end encrypted.',
    version: '0.1.0',
    launchPath: '/maps',
    // ⚠ The permissions listed here are DISPLAY data — what the app can actually call is `methods`.
    permissions: [
      {
        id: 'place.read',
        label: 'Read your places',
        description: 'See your places, where they are, and how often you have been there.',
        state: 'granted',
        lastUsedAtMs: null,
      },
      {
        id: 'place.write',
        label: 'Rename your places',
        description: 'Give a place a name. Renaming is the only change Maps on the web can make.',
        state: 'granted',
        lastUsedAtMs: null,
      },
      {
        id: 'map.read',
        label: 'Draw maps',
        description: 'Read map tiles for the area on screen through Tenshu. Nothing is fetched from a map provider.',
        state: 'granted',
        lastUsedAtMs: null,
      },
    ],
    services: [
      {
        id: 'place',
        label: 'PlaceService',
        reason: 'Stores your places, their names and labels.',
      },
      {
        id: 'timeline',
        label: 'TimelineService',
        reason: 'Counts your visits to a place. Read only.',
      },
    ],
  },
}

export default maps
